local R6Limbs={
   ["Head"]=true,
   ["Left Leg"]=true,
   ["Right Leg"]=true,
   ["Left Arm"]=true,
   ["Right Arm"]=true,
}
for _,k in next,data do
   local kf=Instance.new("Keyframe")
   kf.Time=k.Time
   kf.Parent=kfs
   local data=k.Data
   if data["HumanoidRootPart"] and not kf:FindFirstChild("HumanoidRootPart") then
      local d=data["HumanoidRootPart"]
      local p=Instance.new("Pose")
      p.Name="HumanoidRootPart"
      p.CFrame=d.CFrame
      p.Weight=d.Weight
      p.EasingDirection=d.EaseDirection
      p.EasingStyle=d.EaseStyle
      p.Parent=kf
   end 
   if data["Torso"] and not kf:FindFirstChild("HumanoidRootPart"):FindFirstChild("Torso") then
      local d=data["Torso"]
      local p=Instance.new("Pose")
      p.Name="Torso"
      p.CFrame=d.CFrame
      p.Weight=d.Weight
      p.EasingDirection=d.EaseDirection
      p.EasingStyle=d.EaseStyle
      p.Parent=kf["HumanoidRootPart"]
   end 
   for i,d in pairs(k.Data) do
      if i:lower()=="humanoidrootpart" or i:lower()=="torso" then continue end
      if R6Limbs[i] then
         local p=Instance.new("Pose")
         p.Name=i
         p.CFrame=d.CFrame
         p.Weight=d.Weight
         p.EasingDirection=d.EaseDirection
         p.EasingStyle=d.EaseStyle
         p.Parent=kf["HumanoidRootPart"]["Torso"]
      else
         local p=Instance.new("Pose")
         p.Name=i
         p.CFrame=d.CFrame
         p.Weight=d.Weight
         p.EasingDirection=d.EaseDirection
         p.EasingStyle=d.EaseStyle
         p.Parent=kf["HumanoidRootPart"]
      end
   end
end
kfs.Parent=workspace
return kfs
